    @Test fun actualStoreFailureHasNoSuccessWhileSuccessfulRescheduleAndCompletionAnnounceAndFocus() = runTest {
        eachLocale { russian ->
            withPublicWorkspace { directory, preferences ->
                val releaseFailure = CompletableDeferred<Unit>()
                var snoozeAttempts = 0
                PublicProductionFixture(directory, preferences, initialScreen = ScreenId.TODAY, decorateManager = { delegate ->
                    object : ScreenDataManager by delegate {
                        override suspend fun execute(screen: ScreenId, command: ScreenCommand): Result<ScreenSnapshot> =
                            if (command.operation == "snooze" && snoozeAttempts++ == 0) {
                                releaseFailure.await()
                                Result.failure(IOException("Injected durable-write failure"))
                            } else delegate.execute(screen, command)
                    }
                }).use { f ->
                    f.seed()
                    val batch = f.database.snapshot().batches.single()
                    val actionId = ScheduledActionId("review-general-task")
                    f.database.saveBatch(batch.copy(actions = batch.actions + ScheduledAction(
                        actionId, batch.id, null, DueMoment.ElapsedTarget(f.now()))))
                    val before = f.database.snapshot()
                    val view = ComposeView(paparazzi.context).apply { setContent { RootApp(f.root, onThemeChanged = {}) } }
                    val future = "2026-10-10T12:00:00Z"
                    fun reschedule() = f.dispatch(UiAction.SubmitItem("snooze", actionId.value,
                        mapOf("dueKind" to "elapsed", "dueAt" to future)))
                    play(view, listOf(
                        {
                            assertTrue(view.tagged("action-completion-status").isEmpty())
                            reschedule()
                            true
                        },
                        {
                            if (!f.model().busy) false else {
                                assertEquals(0L, f.model().completionRevision)
                                assertTrue(view.tagged("action-completion-status").isEmpty())
                                releaseFailure.complete(Unit)
                                true
                            }
                        },
                        {
                            if (f.model().errorKey == null) false else {
                                assertEquals(before, f.database.snapshot())
                                assertEquals(0L, f.model().completionRevision)
                                assertNull(f.model().lastCompletedOperation)
                                assertTrue(view.tagged("action-completion-status").isEmpty())
                                reschedule()
                                true
                            }
                        },
                        {
                            val status = view.tagged("action-completion-status").singleOrNull()
                            if (status?.config?.getOrNull(SemanticsProperties.Focused) != true) false else {
                                assertEquals("snooze", f.model().lastCompletedOperation)
                                assertEquals(1L, f.model().completionRevision)
                                assertEquals(LiveRegionMode.Polite, status.config.getOrNull(SemanticsProperties.LiveRegion))
                                assertEquals(listOf(if (russian) "Задача перенесена." else "Task rescheduled."), status.texts())
                                val saved = f.database.snapshot().batches.single().actions.single { it.id == actionId }
                                assertEquals(DueMoment.ElapsedTarget(Instant.parse(future)), saved.due)
                                f.dispatch(UiAction.SubmitItem("complete-action", actionId.value))
                                true
                            }
                        },
                        {
                            val status = view.tagged("action-completion-status").singleOrNull()
                            val expected = if (russian) "Задача выполнена." else "Task completed."
                            if (status?.config?.getOrNull(SemanticsProperties.Focused) != true || expected !in status.texts()) false else {
                                assertEquals("complete-action", f.model().lastCompletedOperation)
                                assertEquals(2L, f.model().completionRevision)
                                assertEquals(LiveRegionMode.Polite, status.config.getOrNull(SemanticsProperties.LiveRegion))
                                assertEquals(ScheduledActionStatus.COMPLETED,
                                    f.database.snapshot().batches.single().actions.single { it.id == actionId }.status)
                                true
                            }
                        },
                    ))
                    assertEquals(2, snoozeAttempts)
                }
            }
        }
    }

    private suspend fun eachLocale(block: suspend (Boolean) -> Unit) {
        val previous = Locale.getDefault()
        try {
            listOf("en", "ru").forEach { language ->
                Locale.setDefault(Locale.forLanguageTag(language))
                paparazzi.unsafeUpdateConfig(deviceConfig = DeviceConfig.PIXEL_5.copy(
                    screenHeight = 3000, fontScale = 2f, locale = language))
                paparazzi.configureComposeResources()
                block(language == "ru")
            }
        } finally { Locale.setDefault(previous) }
    }

    private fun play(view: View, steps: List<suspend () -> Boolean>) {
        var step = 0
        onFrame = { if (step < steps.size && runBlocking { steps[step]() }) step += 1 }
        try { paparazzi.gif(view, start = 0L, end = 5_000L, fps = 10) } finally { onFrame = {} }
        assertEquals(steps.size, step, "Stopped at step $step; semantics=${view.nodes().map { it.config }}")
    }

    private fun View.nodes(): List<SemanticsNode> = buildList {
        if (this@nodes is ViewRootForTest) addAll(semanticsOwner.getAllSemanticsNodes(mergingEnabled = true))
        if (this@nodes is ViewGroup) repeat(childCount) { addAll(getChildAt(it).nodes()) }
    }
    private fun View.tagged(tag: String) = nodes().filter { it.config.getOrNull(SemanticsProperties.TestTag) == tag }
    private fun SemanticsNode.texts() = config.getOrNull(SemanticsProperties.Text).orEmpty().map { it.text }
}
# Requirements corrections — 2026-10-24

The original read-only review is preserved in `source/review.json`. This document describes the implementation delta; it is not an independent acceptance verdict.

| Finding | Correction | Behavioral regression coverage |
| --- | --- | --- |
| F01 | An open advertising visit expires with its privacy eligibility. The native factory and callbacks recheck eligibility immediately before requesting or accepting a banner. | `AdvertisingRootProductionTest.privacyExpiryCollapsesTheOpenVisitAndPreventsAnyReload`; `AdvertisingRequestBoundaryTest` |
| F02 | The screen visit owns the single-load session across lazy-item recycling. Failure/disposal removes the entire slot. The primary action has a measured footer while an ad is eligible. | Compact actual-root scroll-out/scroll-in scenario, no-fill spacing and ad/footer bounds in `AdvertisingRootProductionTest` |
| F03 | Assigned active batches expose the temporary-unassigned action. The real stage editor can select unassigned placement and preview it before committing. | `DataLifecycleRegressionProductionTest`: public root/Store actions, full destination, preview, invocation identity and SQLite reopen |
| F04 | Closing captures the current placement independently of active occupancy. History/detail resolve the saved name after a zone rename/delete. Legacy payloads retain their event fallback; repeating a batch resets the closed placement. | All three outcomes, corrected placement, zone rename/delete, reopen, repeat and legacy decoding in `DataLifecycleRegressionProductionTest` |
| F05 | Restore rejects duplicate action IDs across different batches before replacing live data. | Corrupt-archive preview/restore preserves database, photos and reminders in `DataLifecycleRegressionProductionTest` |
| F06 | Tray rows expose localized rectangle/circle geometry and metric dimensions, with compact integer formatting. | Actual clickable EN/RU rows at 200% in `ReviewAccessibilityProductionTest`; existing tray goldens |
| F07 | Date, time and clear controls expose their field context and associated validation error in semantics. Date/time controls separately expose their localized selected value or empty-selection prompt as `stateDescription`. | Two differently valued temporal fields, contextual names, selected/empty state values, errors and clear target in EN/RU at 200% in `ReviewAccessibilityProductionTest` |
| F08 | Actual committed operations produce localized polite success status and an explicit focus destination. Pending and failed operations do not report success. | Actual retained Store delayed failure → retry → saved due time → completion, EN/RU at 200%, in `ReviewAccessibilityProductionTest` |
| F09 | Existing/current work uses a native repeating daily calendar summary. Future-only work starts its dated queue at the first useful date and replenishes on foreground reconciliation. | Beyond-30-day/future-only/cancellation shared integration scenarios plus `IosReminderTriggerTest` |
| F10 | Android permission recheck distinguishes initial, rationale and permanent denial using the remembered request and current platform state; permanent denial does not launch a futile request. | `AndroidNotificationPermissionPolicyTest`; isolated Android runtime check is separate evidence |

The user approved the future-only iOS scheduling boundary in [DEC-20261024-ios-summary-horizon](../../decisions/DEC-20261024-ios-summary-horizon.md). The adopted spec retains every acceptance ID and required verification surface.

The temporal-value follow-up keeps a contextual name and a separate state value. TalkBack's [node feedback implementation](https://raw.githubusercontent.com/google/talkback/master/talkback/src/main/java/com/google/android/accessibility/talkback/compositor/AccessibilityNodeFeedbackUtils.java) prefers a nonempty content description over node text; its [default role description](https://raw.githubusercontent.com/google/talkback/master/talkback/src/main/java/com/google/android/accessibility/talkback/compositor/roledescription/DefaultDescription.java) obtains state independently. The selected-value and empty-selection regressions first failed with absent state values, then passed after explicitly exposing the same localized value shown by each button. This code/test proof does not replace natural TalkBack utterance acceptance.

